#!/usr/bin/env python3
"""Subsets the Lucide icon font (npm lucide-static: font/lucide.ttf + font/info.json) to the icons
listed below and writes assets/Lucide-icons.ttf + app/icons.h.
Usage: make_icons.py lucide.ttf info.json assets/Lucide-icons.ttf app/icons.h  (needs pyftsubset)
"""
import json,sys,subprocess
src,info,out_ttf,out_h=sys.argv[1:5]
d=json.load(open(info))
icons=[('HOME','house'),('SHELF','library-big'),('BOOK','book-open'),('BOOK_TEXT','book-open-text'),('DISCOVER','compass'),('APPS','layout-grid'),
('MUSIC','music'),('MIC','mic'),('SMARTHOME','house-plug'),('SETTINGS','settings'),('TRANSFER','folder-sync'),('TOUCH','pointer'),
('VOCAB','graduation-cap'),('DICT','book-a'),('SEARCH','search'),('WIFI','wifi'),('WIFI_OFF','wifi-off'),('BT','bluetooth'),('SUN','sun'),('SUN_DIM','sun-dim'),
('REFRESH','refresh-cw'),('MOON','moon'),('BAT_FULL','battery-full'),('BAT_MED','battery-medium'),('BAT_LOW','battery-low'),('BAT_EMPTY','battery'),
('BAT_CHARGE','battery-charging'),('FOLDER','folder'),('SD','memory-stick'),('FONT','type'),('BOOKMARK','bookmark'),('DOWNLOAD','cloud-download'),
('USER','user-round'),('CHEV_R','chevron-right'),('CHEV_L','chevron-left'),('CHEV_D','chevron-down'),('X','x'),('CHECK','check'),('LIST','list'),('CLOCK','clock'),
('FLAME','flame'),('STAR','star'),('VOLUME','volume-2'),('TRASH','trash-2'),('PLUS','plus'),('MINUS','minus'),('ROTATE','rotate-cw'),('POWER','power'),
('PLAY','play'),('PAUSE','pause'),('PREV','skip-back'),('NEXT','skip-forward'),('SHUFFLE','shuffle'),('REPEAT','repeat'),('BRAIN','brain'),
('TROPHY','trophy'),('CALENDAR','calendar-days'),('SLIDERS','sliders-horizontal'),('KEYBOARD','keyboard'),('INFO','info'),('DRIVE','hard-drive'),
('FILE','file-text'),('DEVICE','tablet-smartphone'),('LANG','languages'),('STOP','square'),('REC','circle-dot'),('LAMP','lamp'),('AC','air-vent'),
('BLINDS','blinds'),('THERMO','thermometer'),('DROPS','droplets'),('LOCK','lock'),('FAN','fan'),('PLUG','plug'),('TV','tv'),('VIBRATE','vibrate'),
('HELP','circle-help'),('SPEAKER','audio-lines'),('SHIELD','shield-check'),('HOURGLASS','hourglass'),('LAYERS','layers'),('SORT','arrow-up-down'),
('UNDO','undo-2'),('EYE','eye'),('SPARKLES','sparkles'),('QUOTE','quote'),('TARGET','target'),('ALIGN','align-justify'),('ARROW_R','arrow-right'),('USB','usb'),('LIGHTBULB','lightbulb'),('NOTES','notebook-pen'),('HIGHLIGHT','highlighter'),('PEN','pen-line'),('QUOTE_TEXT','text-quote'),('SHARE','share'),('NOTE','sticky-note')]
cps=[]; lines=['// Generated by tools/make_icons.py from lucide-static (ISC licence). Line icons for e-ink.','#pragma once','namespace icon {']
for m,n in icons:
    if n not in d: print('MISSING',n); sys.exit(1)
    cp=int(d[n]['encodedCode'].lstrip('\\'),16); cps.append(cp)
    u=chr(cp).encode(); lines.append('constexpr const char* %s = "%s";  // %s' % (m,''.join('\\x%02X'%b for b in u),n))
lines.append('}  // namespace icon'); open(out_h,'w').write('\n'.join(lines)+'\n')
subprocess.check_call(['pyftsubset',src,'--unicodes='+','.join('U+%04X'%c for c in cps),'--output-file='+out_ttf,'--no-hinting','--layout-features=','--notdef-outline'])
print(len(cps),'icons')
